function examining(){return `<div class="screen-heading">${visual('blick')}<div><div class="eyebrow">B1 Weitblick · B2 Perspektivwechsel</div><h1>Prüfen</h1><p>Verstehen · Gestalten · Handeln. Wähle nach deiner Frage, nicht nach einer vorgegebenen Reihenfolge.</p></div></div><div class="grid">${[['pruefen-a','A · VERSTEHEN','Was soll eine Aufgabe zeigen – und was kann ich am Ergebnis tatsächlich erkennen?'],['pruefen-b','B · GESTALTEN','Eine eigene Aufgabe weiterentwickeln: Prüfziel, KI-Rolle, Evidenz und Bewertung.'],['pruefen-c','C · HANDELN','JETZT – KORREKTUR – GEMEINSAM. Konkreter Verdacht in der Sek I und schulischer Klärungsbedarf.']].map(([id,title,p])=>`<article class="horizon sand"><h2>${title}</h2><p>${p}</p><a class="button secondary" href="#${id}">Arbeitsweg öffnen</a></article>`).join('')}</div><div class="subtle"><h3>Begleitung für deinen Einstieg</h3><p>Sprich einen Coach an, wenn du neu in einen begleiteten Arbeitsweg einsteigst. Für C ist fachkundige Begleitung vorgesehen.</p><a href="#coaches">Coaches finden</a></div>`}
